import json
from taf.ul.auto_commissioning.data_storage.base import BasaDataStorage


class JsonDataStorage(BasaDataStorage):
    """Stores data of json format on hard drive"""

    def __init__(self, address):
        self.address = address

    def load(self):
        with open(self.address) as fp:
            return json.load(fp)

    def save(self, data):
        with open(self.address, "w") as fp:
            json.dump(data, fp)
